window.TEXTOS_SEED["isaias"][36] = [
{s:"Senaquerib ameaça Jerusalém"},
{v:1,t:"No décimo quarto ano do rei Ezequias, Senaquerib, rei da Assíria, subiu contra todas as cidades fortificadas de Judá e as tomou.",n:"Os capítulos 36–39 reproduzem, com poucas diferenças, 2 Reis 18,13–20,19. Os fatos são de 701 antes de Cristo."},
{v:2,t:"O rei da Assíria enviou de Laquis a Jerusalém, ao rei Ezequias, o Rabsaces, com um poderoso exército. Ele parou junto ao aqueduto do tanque superior, no caminho do campo do Pisoeiro.",n:"Rabsaces: título de um alto oficial assírio."},
{v:3,t:"Saíram ao seu encontro Eliacim, filho de Helcias, mordomo do palácio, Sobna, o escriba, e Joaé, filho de Asaf, o arauto."},
{v:4,t:"O Rabsaces lhes disse: Dizei a Ezequias: Assim diz o grande rei, o rei da Assíria: Que confiança é essa em que te apoias?"},
{v:5,t:"Dizes que simples palavras valem por conselho e força para a guerra? Em quem confias, para te revoltares contra mim?"},
{v:6,t:"Confias no Egito, essa cana rachada, que penetra e fura a mão de quem nela se apoia? Assim é o faraó, rei do Egito, para todos os que nele confiam."},
{v:7,t:"E, se me disseres: Confiamos no Senhor nosso Deus, não foi dele que Ezequias suprimiu os lugares altos e os altares, dizendo a Judá e a Jerusalém: Adorareis diante deste altar?"},
{v:8,t:"Agora, pois, faze uma aposta com o meu senhor, o rei da Assíria: eu te darei dois mil cavalos, se puderes encontrar cavaleiros para montá-los!"},
{v:9,t:"Como poderias repelir um só governador, o menor dos servos do meu senhor? E confias no Egito por causa dos carros e dos cavaleiros!"},
{v:10,t:"E, além disso, foi sem a vontade do Senhor que subi contra esta terra para destruí-la? Foi o Senhor que me disse: Sobe contra esta terra e destrói-a!"},
{v:11,t:"Eliacim, Sobna e Joaé disseram ao Rabsaces: Fala aos teus servos em aramaico, porque nós o entendemos; não nos fales em judaico, aos ouvidos do povo que está sobre a muralha.",np:1},
{v:12,t:"Mas o Rabsaces respondeu: Foi ao teu senhor e a ti que o meu senhor me mandou dizer estas palavras? Não foi antes aos homens que estão sentados sobre a muralha, condenados como vós a comer os próprios excrementos e a beber a própria urina?"},
{v:13,t:"Então o Rabsaces pôs-se de pé e gritou em alta voz, em judaico: Ouvi as palavras do grande rei, o rei da Assíria!",np:1},
{v:14,t:"Assim diz o rei: Que Ezequias não vos engane, porque ele não poderá livrar-vos!"},
{v:15,t:"Que Ezequias não vos faça confiar no Senhor, dizendo: O Senhor certamente nos livrará, e esta cidade não será entregue nas mãos do rei da Assíria."},
{v:16,t:"Não ouçais Ezequias! Porque assim diz o rei da Assíria: Fazei a paz comigo e rendei-vos a mim, e cada um comerá da sua vinha e da sua figueira, e beberá da água da sua cisterna,"},
{v:17,t:"até que eu venha e vos leve para uma terra semelhante à vossa, terra de trigo e de vinho, terra de pão e de vinhas."},
{v:18,t:"Que Ezequias não vos engane, dizendo: O Senhor nos livrará! Acaso os deuses das nações livraram cada um a sua terra da mão do rei da Assíria?"},
{v:19,t:"Onde estão os deuses de Emat e de Arfad? Onde estão os deuses de Sefarvaim? Acaso livraram Samaria da minha mão?"},
{v:20,t:"Qual dentre todos os deuses destes países livrou a sua terra da minha mão, para que o Senhor possa livrar Jerusalém da minha mão?",np:1},
{v:21,t:"Eles ficaram calados e não lhe responderam uma palavra, porque o rei tinha dado esta ordem: Não lhe respondais.",np:1},
{v:22,t:"Então Eliacim, filho de Helcias, mordomo do palácio, Sobna, o escriba, e Joaé, filho de Asaf, o arauto, foram ter com Ezequias, com as vestes rasgadas, e lhe contaram as palavras do Rabsaces."}
];

window.TEXTOS_SEED["isaias"][37] = [
{s:"Ezequias consulta Isaías"},
{v:1,t:"Quando o rei Ezequias ouviu isso, rasgou as vestes, cobriu-se de pano de saco e foi à casa do Senhor."},
{v:2,t:"E enviou Eliacim, mordomo do palácio, Sobna, o escriba, e os anciãos dos sacerdotes, cobertos de pano de saco, ao profeta Isaías, filho de Amós."},
{v:3,t:"Eles lhe disseram: Assim diz Ezequias: Este é um dia de angústia, de castigo e de afronta: os filhos chegaram à hora do parto, e não há força para dar à luz."},
{v:4,t:"Talvez o Senhor teu Deus ouça as palavras do Rabsaces, a quem o rei da Assíria, seu senhor, enviou para insultar o Deus vivo, e castigue as palavras que o Senhor teu Deus ouviu. Eleva, pois, uma oração pelo resto que ainda subsiste."},
{v:5,t:"Os servos do rei Ezequias foram ter com Isaías,",np:1},
{v:6,t:"e Isaías lhes disse: Assim direis ao vosso senhor: Assim diz o Senhor: Não tenhas medo das palavras que ouviste, com as quais os servos do rei da Assíria me insultaram."},
{v:7,t:"Eis que porei nele um espírito: ele ouvirá uma notícia e voltará para a sua terra, e na sua terra eu o farei cair à espada."},
{s:"Nova ameaça de Senaquerib"},
{v:8,t:"O Rabsaces voltou e encontrou o rei da Assíria atacando Lebna, porque tinha sabido que o rei partira de Laquis."},
{v:9,t:"Então o rei ouviu dizer que Taraca, rei da Etiópia, tinha saído para combatê-lo. Ao ouvir isso, enviou mensageiros a Ezequias, para lhe dizer:"},
{v:10,t:"Assim direis a Ezequias, rei de Judá: Que o teu Deus, em quem confias, não te engane, dizendo: Jerusalém não será entregue nas mãos do rei da Assíria."},
{v:11,t:"Tu mesmo ouviste o que os reis da Assíria fizeram a todos os países, votando-os ao extermínio; e tu escaparias?"},
{v:12,t:"Acaso os deuses das nações que os meus pais destruíram livraram-nas: Gozã, Harã, Resef e os filhos de Éden, que estavam em Telassar?"},
{v:13,t:"Onde estão o rei de Emat, o rei de Arfad e o rei da cidade de Sefarvaim, de Ana e de Ava?"},
{s:"A oração de Ezequias"},
{v:14,t:"Ezequias recebeu a carta das mãos dos mensageiros e a leu; depois subiu à casa do Senhor e a abriu diante do Senhor."},
{v:15,t:"E Ezequias orou ao Senhor, dizendo:",np:1},
{v:16,t:"Senhor dos exércitos, Deus de Israel, que estás sentado sobre os querubins, só tu és Deus de todos os reinos da terra; tu fizeste o céu e a terra."},
{v:17,t:"Inclina, Senhor, o teu ouvido e ouve; abre, Senhor, os teus olhos e vê; ouve todas as palavras que Senaquerib mandou para insultar o Deus vivo."},
{v:18,t:"É verdade, Senhor, que os reis da Assíria devastaram todos os países e as suas terras,"},
{v:19,t:"e lançaram ao fogo os seus deuses; é que não eram deuses, mas obra de mãos humanas, madeira e pedra; por isso os destruíram."},
{v:20,t:"Agora, pois, Senhor nosso Deus, salva-nos da sua mão, para que todos os reinos da terra saibam que só tu és o Senhor."},
{s:"A resposta do Senhor por meio de Isaías"},
{v:21,t:"Então Isaías, filho de Amós, mandou dizer a Ezequias: Assim diz o Senhor, Deus de Israel: Quanto à oração que me fizeste a respeito de Senaquerib, rei da Assíria,"},
{v:22,l:["esta é a palavra que o Senhor pronunciou contra ele:","Ela te despreza e zomba de ti,","a virgem, filha de Sião;","atrás de ti meneia a cabeça","a filha de Jerusalém."]},
{v:23,l:["A quem insultaste e blasfemaste?","Contra quem levantaste a voz","e ergueste com altivez os teus olhos?","Contra o Santo de Israel!"],np:1},
{v:24,l:["Por meio dos teus servos","insultaste o Senhor,","e disseste: Com a multidão dos meus carros","subi aos cumes dos montes, às alturas do Líbano;","cortei os seus cedros mais altos,","os seus ciprestes mais belos;","cheguei ao seu cume mais alto,","à sua floresta mais densa."],np:1},
{v:25,l:["Cavei poços e bebi águas estrangeiras;","com a planta dos meus pés","sequei todos os rios do Egito."],np:1},
{v:26,l:["Não ouviste","que foi eu que preparei isto há muito tempo?","Desde os dias antigos o planejei,","e agora o fiz acontecer:","tu estavas destinado a arrasar","cidades fortificadas, reduzindo-as a montões de ruínas."],np:1},
{v:27,l:["Os seus habitantes, sem forças,","tremeram e ficaram confusos;","tornaram-se como a erva do campo,","como a relva verde,","como o capim dos telhados,","que seca antes de amadurecer."],np:1},
{v:28,l:["Eu sei quando te sentas,","quando sais e quando entras,","e conheço o teu furor contra mim."],np:1},
{v:29,l:["Porque te enfureceste contra mim,","e a tua arrogância subiu aos meus ouvidos,","porei a minha argola no teu nariz","e o meu freio nos teus lábios,","e te farei voltar pelo caminho","por onde vieste."],np:1},
{v:30,l:["E para ti, Ezequias, este será o sinal:","este ano comereis o que brotar dos grãos caídos,","e no segundo ano o que nascer por si mesmo;","mas no terceiro ano semeai e colhei,","plantai vinhas e comei os seus frutos."],np:1},
{v:31,l:["O resto que escapar da casa de Judá","lançará raízes para baixo","e dará frutos para cima;"],np:1},
{v:32,l:["porque de Jerusalém sairá um resto,","e do monte Sião, sobreviventes.","O zelo do Senhor dos exércitos fará isto."],np:1},
{v:33,l:["Por isso, assim diz o Senhor a respeito do rei da Assíria:","Ele não entrará nesta cidade,","nem atirará nela uma flecha,","nem a enfrentará com escudo,","nem levantará contra ela rampas de cerco."],np:1},
{v:34,l:["Pelo caminho por onde veio voltará,","e nesta cidade não entrará,","oráculo do Senhor."],np:1},
{v:35,l:["Protegerei esta cidade e a salvarei,","por amor de mim e de Davi, meu servo."],np:1},
{v:36,t:"O anjo do Senhor saiu e feriu no acampamento dos assírios cento e oitenta e cinco mil homens. Quando se levantaram de manhã, só havia cadáveres.",np:1},
{v:37,t:"Senaquerib, rei da Assíria, levantou acampamento, partiu e voltou; e ficou em Nínive.",np:1},
{v:38,t:"Um dia, quando adorava no templo de Nesroc, seu deus, Adramelec e Sarasar, seus filhos, o mataram à espada e fugiram para a terra de Ararat. E seu filho Asaradon reinou em seu lugar."}
];

window.TEXTOS_SEED["isaias"][38] = [
{s:"A doença e a cura de Ezequias"},
{v:1,t:"Naqueles dias, Ezequias caiu gravemente doente, à beira da morte. O profeta Isaías, filho de Amós, veio ter com ele e disse-lhe: Assim diz o Senhor: Põe em ordem a tua casa, porque vais morrer; não viverás."},
{v:2,t:"Ezequias voltou o rosto para a parede e orou ao Senhor,"},
{v:3,t:"dizendo: Ah, Senhor, lembra-te de que andei diante de ti com fidelidade e de coração íntegro, e fiz o que é bom aos teus olhos! E Ezequias chorou muito."},
{v:4,t:"Então a palavra do Senhor foi dirigida a Isaías nestes termos:",np:1},
{v:5,t:"Vai e dize a Ezequias: Assim diz o Senhor, Deus de Davi, teu pai: Ouvi a tua oração, vi as tuas lágrimas; eis que acrescentarei quinze anos à tua vida;"},
{v:6,t:"e te livrarei, a ti e a esta cidade, da mão do rei da Assíria, e protegerei esta cidade."},
{v:7,t:"Este será para ti o sinal, da parte do Senhor, de que o Senhor cumprirá a palavra que disse:"},
{v:8,t:"Eis que farei recuar dez degraus a sombra que já desceu, com o sol, nos degraus de Acaz. E o sol recuou dez degraus nos degraus que tinha descido.",n:"Os degraus de Acaz: talvez uma escadaria que servia de relógio de sol."},
{s:"O cântico de Ezequias"},
{v:9,t:"Cântico escrito por Ezequias, rei de Judá, quando esteve doente e se curou da sua doença:"},
{v:10,l:["Eu dizia: Na metade dos meus dias","devo partir para as portas da morada dos mortos;","fui privado do resto dos meus anos."],np:1},
{v:11,l:["Eu dizia: Não verei mais o Senhor","na terra dos vivos,","não verei mais nenhum homem","entre os habitantes do mundo."],np:1},
{v:12,l:["A minha morada é arrancada e levada para longe de mim,","como uma tenda de pastores;","como um tecelão, enrolei a minha vida,","e ele me corta do tear.","Do dia para a noite acabas comigo."],np:1},
{v:13,l:["Fiquei prostrado até de manhã;","como um leão, ele quebra todos os meus ossos;","do dia para a noite acabas comigo."],np:1},
{v:14,l:["Como a andorinha, eu pio,","gemo como a pomba;","os meus olhos se cansam de olhar para o alto.","Senhor, estou oprimido:","sê o meu fiador!"],np:1},
{v:15,l:["Que direi? Ele me falou,","e ele mesmo o fez!","Caminharei lentamente todos os meus anos,","na amargura da minha alma."],np:1},
{v:16,l:["Senhor, em ti espera o meu coração;","que o meu espírito viva:","cura-me e faze-me viver."],np:1,n:"Hebraico obscuro; a Nova Vulgata entende, como aqui: em ti espera o meu coração."},
{v:17,l:["Eis que a minha amargura se transformou em paz.","Tu livraste a minha vida","da cova da destruição,","pois lançaste para trás das tuas costas","todos os meus pecados."],np:1},
{v:18,l:["Pois a morada dos mortos não te louva,","a morte não te celebra;","os que descem à cova não esperam","na tua fidelidade."],np:1},
{v:19,l:["O vivo, só o vivo te louva,","como eu faço hoje;","o pai dá a conhecer aos filhos a tua fidelidade."],np:1},
{v:20,l:["Senhor, salva-me,","e ao som das cítaras cantaremos","todos os dias da nossa vida","na casa do Senhor."],np:1},
{v:21,t:"Isaías tinha dito: Tragam uma pasta de figos e a apliquem sobre a úlcera, e ele se curará.",np:1,n:"Os versículos 21–22 correspondem a 2 Reis 20,7–8, onde estão no lugar próprio da narrativa."},
{v:22,t:"E Ezequias tinha perguntado: Qual é o sinal de que subirei à casa do Senhor?"}
];

window.TEXTOS_SEED["isaias"][39] = [
{s:"A embaixada da Babilônia"},
{v:1,t:"Naquele tempo, Merodac-Baladã, filho de Baladã, rei da Babilônia, enviou cartas e um presente a Ezequias, porque soubera que ele estivera doente e se restabelecera."},
{v:2,t:"Ezequias alegrou-se com a chegada deles e mostrou-lhes a sua casa do tesouro: a prata, o ouro, os perfumes e o azeite fino, todo o seu arsenal e tudo o que havia nos seus tesouros. Não houve nada em sua casa e em todo o seu domínio que Ezequias não lhes mostrasse."},
{v:3,t:"Então o profeta Isaías veio ter com o rei Ezequias e lhe perguntou: Que disseram esses homens, e de onde vieram a ti? Ezequias respondeu: Vieram de uma terra distante, da Babilônia.",np:1},
{v:4,t:"Isaías perguntou: Que viram em tua casa? Ezequias respondeu: Viram tudo o que há em minha casa; não há nada nos meus tesouros que eu não lhes tenha mostrado."},
{v:5,t:"Então Isaías disse a Ezequias: Ouve a palavra do Senhor dos exércitos:",np:1},
{v:6,t:"Eis que virão dias em que tudo o que há em tua casa, e o que os teus pais acumularam até hoje, será levado para a Babilônia; não ficará nada, diz o Senhor."},
{v:7,t:"E dos filhos que sairão de ti, que tu gerarás, tomarão alguns para serem eunucos no palácio do rei da Babilônia."},
{v:8,t:"Ezequias disse a Isaías: É boa a palavra do Senhor que disseste. Pois pensava: Haverá paz e segurança enquanto eu viver."}
];

window.TEXTOS_SEED["isaias"][40] = [
{s:"Consolai o meu povo"},
{v:1,l:["Consolai, consolai o meu povo,","diz o vosso Deus."],n:"Começa aqui a segunda parte do livro (capítulos 40–55), chamada Livro da Consolação, dirigida aos exilados na Babilônia, por volta de 550–540 antes de Cristo."},
{v:2,l:["Falai ao coração de Jerusalém","e proclamai-lhe","que terminou o seu tempo de serviço,","que a sua culpa está expiada,","que ela recebeu da mão do Senhor","o dobro por todos os seus pecados."],np:1},
{v:3,l:["Uma voz clama:","Preparai no deserto o caminho do Senhor,","aplanai na estepe","uma estrada para o nosso Deus."],np:1,n:"Os evangelhos aplicam estas palavras a João Batista, lendo com a tradução grega: uma voz clama no deserto (Mateus 3,3; João 1,23)."},
{v:4,l:["Todo vale seja aterrado,","todo monte e toda colina sejam rebaixados;","o terreno acidentado se torne plano,","e as escarpas, planície."],np:1},
{v:5,l:["Então se revelará a glória do Senhor,","e toda carne a verá ao mesmo tempo,","pois a boca do Senhor falou."],np:1},
{v:6,l:["Uma voz diz: Clama!","E eu disse: Que devo clamar?","Toda carne é erva,","e toda a sua beleza é como a flor do campo."],np:1,n:"E eu disse: assim a Nova Vulgata, com o rolo de Isaías de Qumran e a tradução grega; o hebraico tradicional diz: e ele disse."},
{v:7,l:["A erva seca, a flor murcha,","quando sopra sobre ela o vento do Senhor.","Sim, o povo é como a erva."],np:1},
{v:8,l:["A erva seca, a flor murcha,","mas a palavra do nosso Deus permanece para sempre."],np:1,n:"Compare 1 Pedro 1,24–25."},
{s:"Eis o vosso Deus"},
{v:9,l:["Sobe a um monte alto,","tu que anuncias a boa-nova a Sião;","levanta com força a tua voz,","tu que anuncias a boa-nova a Jerusalém;","levanta-a, não tenhas medo;","dize às cidades de Judá:","Eis o vosso Deus!"]},
{v:10,l:["Eis o Senhor Deus, que vem com poder,","e o seu braço domina;","eis que traz consigo o seu prêmio,","e a sua recompensa vai à sua frente."],np:1},
{v:11,l:["Como um pastor, ele apascenta o seu rebanho;","com o braço reúne os cordeiros,","carrega-os no colo","e conduz com cuidado as ovelhas que amamentam."],np:1},
{s:"A grandeza do Criador"},
{v:12,l:["Quem mediu as águas na concha da mão","e calculou o céu com o palmo,","quem mediu com um alqueire o pó da terra","e pesou os montes na balança","e as colinas nos pratos?"]},
{v:13,l:["Quem dirigiu o espírito do Senhor,","ou quem foi o seu conselheiro","e lhe ensinou alguma coisa?"],np:1,n:"Paulo cita este versículo em Romanos 11,34 e 1 Coríntios 2,16."},
{v:14,l:["Com quem ele se aconselhou, para que o instruísse,","lhe ensinasse o caminho do direito,","lhe comunicasse o conhecimento","e lhe mostrasse a via da inteligência?"],np:1},
{v:15,l:["Eis que as nações são como uma gota num balde,","valem como um grão de poeira na balança;","eis que ele levanta as ilhas como um grão de pó."],np:1},
{v:16,l:["O Líbano não bastaria para a lenha,","e os seus animais não bastariam para o holocausto."],np:1},
{v:17,l:["Todas as nações são como nada diante dele,","ele as considera como nada e vazio."],np:1},
{v:18,l:["A quem, pois, comparareis Deus?","Que imagem poreis ao lado dele?"],np:1},
{v:19,l:["O artesão funde uma imagem,","o ourives a reveste de ouro","e lhe solda correntinhas de prata."],np:1},
{v:20,l:["Quem é pobre demais para tal oferta","escolhe uma madeira que não apodrece","e procura um artesão hábil","para fazer uma imagem que não se mova."],np:1},
{v:21,l:["Não sabeis? Não ouvistes?","Não vos foi anunciado desde o princípio?","Não compreendestes os fundamentos da terra?"],np:1},
{v:22,l:["Ele está sentado sobre o círculo da terra,","e os seus habitantes são como gafanhotos;","estende os céus como um véu","e os desdobra como uma tenda para morar."],np:1},
{v:23,l:["Reduz a nada os príncipes","e torna vazios os juízes da terra."],np:1},
{v:24,l:["Mal foram plantados,","mal foram semeados,","mal o seu tronco lançou raízes na terra,","ele sopra sobre eles, e secam,","e o furacão os leva como palha."],np:1},
{v:25,l:["A quem me comparareis,","a quem eu seria igual?","— diz o Santo."],np:1},
{v:26,l:["Erguei os olhos para o alto","e vede: quem criou estas coisas?","Aquele que faz sair em número o seu exército","e chama cada estrela pelo nome;","tão grande é o seu vigor e tão forte o seu poder,","que nenhuma falta."],np:1},
{v:27,l:["Por que dizes, Jacó,","e por que afirmas, Israel:","O meu caminho está escondido do Senhor,","e o meu direito escapa ao meu Deus?"],np:1},
{v:28,l:["Não sabes? Não ouviste?","O Senhor é um Deus eterno,","que criou os confins da terra;","ele não se cansa nem se fatiga,","e a sua inteligência é insondável."],np:1},
{v:29,l:["Ele dá força ao cansado","e multiplica o vigor do fraco."]},
{v:30,l:["Os jovens se cansam e se fatigam,","os rapazes tropeçam e caem;"],np:1},
{v:31,l:["mas os que esperam no Senhor renovam as suas forças,","criam asas como as águias,","correm e não se fatigam,","caminham e não se cansam."],np:1}
];

window.TEXTOS_SEED["isaias"][41] = [
{s:"O Senhor, senhor da história"},
{v:1,l:["Calai-vos diante de mim, ilhas,","e que os povos renovem as suas forças;","que se aproximem e depois falem:","compareçamos juntos em julgamento."]},
{v:2,l:["Quem suscitou do Oriente aquele","a quem a vitória acompanha a cada passo?","Quem lhe entrega as nações","e lhe submete os reis?","A sua espada os reduz a pó,","o seu arco, a palha levada pelo vento."],np:1,n:"Ciro, rei da Pérsia, que conquistou a Babilônia em 539 antes de Cristo e permitiu a volta dos exilados (compare 44,28; 45,1)."},
{v:3,l:["Ele os persegue e passa em segurança","por um caminho que os seus pés nunca pisaram."],np:1},
{v:4,l:["Quem fez e realizou isto?","Aquele que chama as gerações desde o princípio.","Eu, o Senhor, sou o primeiro,","e com os últimos serei o mesmo."],np:1},
{v:5,l:["As ilhas viram e ficaram com medo,","os confins da terra tremeram;","aproximaram-se e vieram."],np:1},
{v:6,l:["Cada um ajuda o seu companheiro","e diz ao seu irmão: Coragem!"],np:1},
{v:7,l:["O artesão anima o ourives,","o que alisa com o martelo anima o que bate na bigorna,","e diz da solda: Está boa;","depois fixa o ídolo com pregos, para que não se mova."],np:1,n:"Ironia contra os fabricantes de ídolos, que se animam uns aos outros diante do Deus verdadeiro."},
{s:"Israel, servo do Senhor"},
{v:8,l:["Mas tu, Israel, meu servo,","Jacó, a quem escolhi,","descendência de Abraão, meu amigo;"]},
{v:9,l:["tu, a quem tomei dos confins da terra","e chamei das suas regiões mais distantes,","e a quem disse: Tu és o meu servo,","eu te escolhi e não te rejeitei:"],np:1},
{v:10,l:["não tenhas medo, pois eu estou contigo;","não te assustes, pois eu sou o teu Deus;","eu te fortaleço e te ajudo,","eu te sustento com a minha mão direita vitoriosa."],np:1},
{v:11,l:["Eis que ficarão envergonhados e confusos","todos os que se irritam contra ti;","serão reduzidos a nada e perecerão","os que te fazem oposição."],np:1},
{v:12,l:["Procurarás, mas não encontrarás","os que brigavam contigo;","serão reduzidos a nada, a coisa nenhuma,","os que te faziam guerra."],np:1},
{v:13,l:["Pois eu, o Senhor, teu Deus,","seguro a tua mão direita","e te digo: Não tenhas medo,","eu te ajudo."],np:1},
{v:14,l:["Não tenhas medo, Jacó, pobre verme,","pequena gente de Israel:","eu te ajudo, oráculo do Senhor;","o teu redentor é o Santo de Israel."],np:1,n:"Redentor: em hebraico goel, o parente próximo que tinha o dever de resgatar o membro da família caído na escravidão ou na miséria (compare Levítico 25,25–49)."},
{v:15,l:["Eis que faço de ti um trilho novo,","cheio de pontas cortantes:","trilharás os montes e os esmigalharás,","e reduzirás as colinas a palha."],np:1},
{v:16,l:["Tu os joeirarás, e o vento os levará,","e o furacão os dispersará;","mas tu te alegrarás no Senhor","e te gloriarás no Santo de Israel."],np:1},
{s:"O deserto transformado"},
{v:17,l:["Os pobres e os necessitados procuram água, e não há;","a sua língua está seca de sede.","Eu, o Senhor, os atenderei;","eu, o Deus de Israel, não os abandonarei."]},
{v:18,l:["Farei brotar rios nas colinas desnudas","e fontes no meio dos vales;","transformarei o deserto num lago","e a terra seca em mananciais."],np:1},
{v:19,l:["Plantarei no deserto o cedro,","a acácia, a murta e a oliveira;","porei na estepe o cipreste,","o olmo e o pinheiro, todos juntos,"],np:1},
{v:20,l:["para que vejam e saibam,","reflitam e compreendam todos","que a mão do Senhor fez isto,","que o Santo de Israel o criou."],np:1},
{s:"O processo contra os ídolos"},
{v:21,l:["Apresentai a vossa causa, diz o Senhor;","trazei as vossas provas, diz o rei de Jacó."]},
{v:22,l:["Que se aproximem e nos anunciem","o que vai acontecer.","Anunciai o que aconteceu antes,","para que reflitamos e conheçamos o seu desfecho;","ou fazei-nos ouvir as coisas futuras."],np:1},
{v:23,l:["Anunciai o que acontecerá no futuro,","para que saibamos que sois deuses;","fazei o bem ou o mal,","para que nos espantemos e o vejamos todos juntos."],np:1},
{v:24,l:["Eis que vós não sois nada,","e a vossa obra não vale nada;","é abominável quem vos escolhe."],np:1},
{v:25,l:["Eu o suscitei do norte, e ele veio;","do Oriente, eu o chamei pelo nome;","ele pisará os governantes como lama,","como o oleiro pisa o barro."],np:1,n:"Eu o chamei pelo nome: assim a Nova Vulgata; o hebraico diz: ele invocará o meu nome."},
{v:26,l:["Quem o anunciou desde o princípio, para que o soubéssemos,","e desde antes, para que disséssemos: É verdade?","Ninguém o anunciou, ninguém o predisse,","ninguém ouviu as vossas palavras."],np:1},
{v:27,l:["Fui eu o primeiro a dizer a Sião: Ei-los aqui!","E dei a Jerusalém um mensageiro de boas-novas."],np:1},
{v:28,l:["Olhei, e não havia ninguém;","entre eles não havia conselheiro","que, interrogado, pudesse responder uma palavra."],np:1},
{v:29,l:["Eis que todos eles são nada,","as suas obras não são nada;","as suas imagens são vento e vazio."],np:1}
];

window.TEXTOS_SEED["isaias"][42] = [
{s:"O primeiro cântico do Servo"},
{v:1,l:["Eis o meu servo, que eu sustento,","o meu escolhido, em quem a minha alma se compraz;","pus sobre ele o meu espírito:","ele levará o direito às nações."],n:"Primeiro dos quatro cânticos do Servo do Senhor (42,1–4; 49,1–6; 50,4–9; 52,13–53,12). O Novo Testamento os aplica a Jesus (Mateus 12,18–21; compare Mateus 3,17)."},
{v:2,l:["Não gritará, não levantará a voz,","não fará ouvir a sua voz nas ruas."],np:1},
{v:3,l:["Não quebrará a cana rachada","nem apagará a mecha que ainda fumega;","com fidelidade levará o direito."],np:1},
{v:4,l:["Não desanimará nem se deixará abater,","até estabelecer o direito na terra;","e as ilhas esperam a sua instrução."],np:1},
{s:"Luz das nações"},
{v:5,l:["Assim diz Deus, o Senhor,","que criou os céus e os estendeu,","que firmou a terra e o que ela produz,","que dá o fôlego ao povo que a habita","e o espírito aos que andam sobre ela:"]},
{v:6,l:["Eu, o Senhor, te chamei na justiça","e te tomei pela mão;","eu te formei e te constituí","aliança do povo e luz das nações,"],np:1,n:"Compare Lucas 2,32."},
{v:7,l:["para abrir os olhos dos cegos,","tirar da prisão os cativos","e do cárcere os que habitam nas trevas."],np:1},
{v:8,l:["Eu sou o Senhor, este é o meu nome;","não darei a outro a minha glória,","nem aos ídolos o meu louvor."],np:1},
{v:9,l:["As coisas antigas, eis que já aconteceram,","e agora anuncio coisas novas;","antes que despontem, eu vos faço ouvi-las."],np:1},
{s:"Cântico novo"},
{v:10,l:["Cantai ao Senhor um cântico novo,","o seu louvor desde os confins da terra,","vós que desceis ao mar e tudo o que ele contém,","ilhas e seus habitantes."]},
{v:11,l:["Levantem a voz o deserto e as suas cidades,","os povoados onde habita Cedar;","exultem os habitantes de Sela,","gritem do alto dos montes."],np:1},
{v:12,l:["Deem glória ao Senhor","e anunciem o seu louvor nas ilhas."],np:1},
{v:13,l:["O Senhor sai como um herói,","como um guerreiro desperta o seu ardor;","lança o grito de guerra, dá o brado,","mostra a sua força contra os inimigos."],np:1},
{v:14,l:["Por muito tempo me calei,","fiquei em silêncio, me contive;","agora grito como a mulher que dá à luz,","ofegante e sufocado ao mesmo tempo."],np:1},
{v:15,l:["Devastarei montes e colinas","e secarei toda a sua vegetação;","transformarei os rios em ilhas","e secarei os lagos."],np:1},
{v:16,l:["Conduzirei os cegos por um caminho que não conhecem","e os farei andar por veredas que ignoram;","diante deles transformarei as trevas em luz","e os terrenos acidentados em planície.","Estas são as coisas que farei,","e não os abandonarei."],np:1},
{v:17,l:["Recuarão, cobertos de vergonha,","os que confiam nos ídolos,","os que dizem às imagens de metal fundido:","Vós sois os nossos deuses."],np:1},
{s:"A cegueira do servo"},
{v:18,l:["Surdos, ouvi!","Cegos, olhai e vede!"]},
{v:19,l:["Quem é cego, senão o meu servo?","Quem é surdo como o mensageiro que envio?","Quem é cego como o meu aliado,","cego como o servo do Senhor?"],np:1,n:"O meu aliado: hebraico de sentido discutido (meshullam); a Nova Vulgata entende: aquele que foi restabelecido. O servo é aqui o povo de Israel, cego e surdo diante da ação de Deus."},
{v:20,l:["Viste muitas coisas, mas não as guardas;","tens os ouvidos abertos, mas não ouves."],np:1},
{v:21,l:["O Senhor quis, por causa da sua justiça,","engrandecer e glorificar a sua instrução."],np:1},
{v:22,l:["Mas este é um povo saqueado e despojado;","todos estão presos em buracos","e escondidos em prisões.","Tornaram-se presa, e não há quem os livre;","despojo, e ninguém diz: Devolve!"],np:1},
{v:23,l:["Quem de vós dará ouvidos a isto,","quem prestará atenção e escutará daqui em diante?"],np:1},
{v:24,l:["Quem entregou Jacó ao saque","e Israel aos saqueadores?","Não foi o Senhor, contra quem pecamos?","Eles não quiseram andar pelos seus caminhos","nem ouviram a sua instrução."],np:1},
{v:25,l:["Por isso derramou sobre ele o ardor da sua ira","e a violência da guerra;","ela o incendiou por todos os lados, mas ele não compreendeu;","o queimou, mas ele não levou isso a sério."],np:1}
];

window.TEXTOS_SEED["isaias"][43] = [
{s:"Eu te resgatei"},
{v:1,l:["Mas agora, assim diz o Senhor,","que te criou, Jacó, e te formou, Israel:","Não tenhas medo, pois eu te resgatei,","eu te chamei pelo nome: tu és meu."]},
{v:2,l:["Quando passares pelas águas, eu estarei contigo,","e os rios não te submergirão;","quando andares pelo fogo, não te queimarás,","e a chama não te consumirá,"],np:1},
{v:3,l:["pois eu sou o Senhor, teu Deus,","o Santo de Israel, o teu salvador:","dei o Egito como resgate por ti,","a Etiópia e Sabá em teu lugar."],np:1},
{v:4,l:["Porque és precioso aos meus olhos,","porque és digno de estima e eu te amo,","dou homens em teu lugar","e povos em troca da tua vida."],np:1},
{v:5,l:["Não tenhas medo, pois eu estou contigo:","do Oriente trarei a tua descendência","e do Ocidente te reunirei."],np:1},
{v:6,l:["Direi ao norte: Entrega!","E ao sul: Não retenhas!","Traze os meus filhos de longe","e as minhas filhas dos confins da terra,"],np:1},
{v:7,l:["todos os que são chamados pelo meu nome,","que eu criei para a minha glória,","que eu formei e fiz."],np:1},
{s:"Israel, testemunha do Senhor"},
{v:8,l:["Faze sair o povo cego, que tem olhos,","e os surdos, que têm ouvidos."]},
{v:9,l:["Que todas as nações se reúnam,","e os povos se juntem:","quem dentre eles anunciou isto","e nos fez ouvir as coisas passadas?","Que apresentem as suas testemunhas para se justificar,","e que se ouça e se diga: É verdade!"],np:1},
{v:10,l:["Vós sois as minhas testemunhas, oráculo do Senhor,","vós e o meu servo, que escolhi,","para que saibais e creiais em mim","e compreendais que eu sou;","antes de mim nenhum deus foi formado,","e depois de mim não haverá nenhum."],np:1,n:"Eu sou: em hebraico ani hu, fórmula com que Deus afirma a sua identidade única (compare João 8,24.28.58)."},
{v:11,l:["Eu, eu sou o Senhor,","e fora de mim não há salvador."],np:1},
{v:12,l:["Fui eu que anunciei e salvei,","eu que o fiz ouvir, e não houve deus estranho entre vós;","vós sois as minhas testemunhas, oráculo do Senhor:","eu sou Deus,"],np:1},
{v:13,l:["desde sempre eu sou.","Ninguém pode livrar da minha mão;","eu ajo, e quem poderá impedi-lo?"],np:1},
{v:14,l:["Assim diz o Senhor, o vosso redentor,","o Santo de Israel:","Por vossa causa mandei atacar a Babilônia","e fiz descer todos os fugitivos,","e os caldeus, nos navios de que se orgulhavam."]},
{v:15,l:["Eu sou o Senhor, o vosso Santo,","o criador de Israel, o vosso rei."],np:1},
{s:"Um novo êxodo"},
{v:16,l:["Assim diz o Senhor,","que abriu um caminho no mar","e uma vereda nas águas impetuosas;"]},
{v:17,l:["que fez sair carros e cavalos,","exército e guerreiros;","caíram todos juntos para não mais se levantar,","apagaram-se, extinguiram-se como um pavio:"],np:1},
{v:18,l:["Não vos lembreis das coisas passadas,","não penseis nas coisas antigas:"],np:1},
{v:19,l:["eis que faço uma coisa nova;","ela já está brotando: não a percebeis?","Sim, abrirei um caminho no deserto","e rios na terra árida."],np:1},
{v:20,l:["Os animais selvagens me glorificarão,","os chacais e os avestruzes,","porque farei brotar água no deserto","e rios na terra árida,","para dar de beber ao meu povo, ao meu escolhido."],np:1},
{v:21,l:["O povo que formei para mim","proclamará o meu louvor."],np:1},
{s:"A infidelidade de Israel"},
{v:22,l:["Mas tu não me invocaste, Jacó;","antes te cansaste de mim, Israel."]},
{v:23,l:["Não me trouxeste os cordeiros dos teus holocaustos,","nem me honraste com os teus sacrifícios;","eu não te sobrecarreguei com ofertas,","nem te cansei com o incenso."],np:1},
{v:24,l:["Não me compraste com dinheiro a cana aromática,","nem me saciaste com a gordura dos teus sacrifícios;","mas tu me sobrecarregaste com os teus pecados,","me cansaste com as tuas iniquidades."],np:1},
{v:25,l:["Sou eu, sou eu mesmo que apago as tuas transgressões, por causa de mim,","e não me lembrarei mais dos teus pecados."],np:1},
{v:26,l:["Faze-me recordar, discutamos juntos;","fala tu mesmo, para te justificares."],np:1},
{v:27,l:["O teu primeiro pai pecou,","e os teus intérpretes se rebelaram contra mim;"],np:1,n:"O primeiro pai: Jacó (compare Oseias 12,3–5)."},
{v:28,l:["por isso profanei os chefes do santuário","e entreguei Jacó ao extermínio,","e Israel aos insultos."],np:1}
];

window.TEXTOS_SEED["isaias"][44] = [
{s:"O espírito derramado sobre Israel"},
{v:1,l:["Mas agora escuta, Jacó, meu servo,","Israel, a quem escolhi."]},
{v:2,l:["Assim diz o Senhor, que te fez,","que te formou desde o ventre materno","e te ajuda:","Não tenhas medo, Jacó, meu servo,","Jesurun, a quem escolhi."],np:1,n:"Jesurun: nome poético de Israel, que significa o reto (compare Deuteronômio 32,15); a Nova Vulgata traduz: amado."},
{v:3,l:["Pois derramarei água sobre o solo sedento","e torrentes sobre a terra seca;","derramarei o meu espírito sobre a tua descendência","e a minha bênção sobre os teus rebentos,"],np:1},
{v:4,l:["e eles brotarão como a erva no meio das águas,","como salgueiros junto às correntes de água."],np:1},
{v:5,l:["Um dirá: Eu sou do Senhor;","outro se chamará pelo nome de Jacó;","outro escreverá na mão: Do Senhor,","e receberá o nome de Israel."],np:1,n:"Escrever na mão o nome do Senhor, como sinal de pertença."},
{s:"Não há outro Deus"},
{v:6,l:["Assim diz o Senhor, rei de Israel,","e o seu redentor, o Senhor dos exércitos:","Eu sou o primeiro e eu sou o último,","e fora de mim não há Deus."],n:"Compare Apocalipse 1,17; 22,13."},
{v:7,l:["Quem é como eu? Que o proclame,","que o anuncie e o exponha diante de mim,","desde que estabeleci o povo antigo;","que anuncie as coisas futuras, as que hão de acontecer."],np:1},
{v:8,l:["Não tenhais medo, não vos assusteis:","não vos fiz ouvir e não vos anunciei isso há muito tempo?","Vós sois as minhas testemunhas.","Existe algum Deus fora de mim?","Não há outra Rocha; não conheço nenhuma."],np:1},
{s:"A insensatez dos ídolos"},
{v:9,t:"Os fabricantes de ídolos não são nada, e as obras que eles tanto amam não servem para nada; as suas testemunhas não veem nem compreendem, para a sua própria vergonha."},
{v:10,t:"Quem fabrica um deus e funde uma imagem que não serve para nada?"},
{v:11,t:"Eis que todos os seus devotos ficarão envergonhados; os artesãos não passam de homens. Que se reúnam todos e compareçam: ficarão aterrados e envergonhados juntos."},
{v:12,t:"O ferreiro trabalha o ferro nas brasas, dá-lhe forma com o martelo e o trabalha com a força do braço; depois tem fome e perde as forças, não bebe água e fica esgotado."},
{v:13,t:"O carpinteiro estende o cordel, desenha a imagem com o giz, trabalha-a com o formão e a traça com o compasso; dá-lhe a forma de um homem, a beleza de uma figura humana, para morar numa casa.",np:1},
{v:14,t:"Ele corta cedros, escolhe um cipreste ou um carvalho e o deixa crescer entre as árvores da floresta; planta um pinheiro, que a chuva faz crescer."},
{v:15,t:"Isso serve ao homem para queimar: ele pega uma parte para se aquecer, acende o fogo e assa pão. Com o resto, fabrica um deus e o adora; faz um ídolo e se prostra diante dele."},
{v:16,t:"Metade da madeira ele queima no fogo e sobre ela assa a carne; come o assado e se sacia; também se aquece e diz: Ah, estou aquecido, sinto o calor do fogo!"},
{v:17,t:"Com o resto faz um deus, o seu ídolo; prostra-se diante dele, adora-o e lhe suplica: Salva-me, pois tu és o meu deus!"},
{v:18,t:"Eles não sabem nem compreendem, porque os seus olhos estão fechados para não ver, e o seu coração, para não entender.",np:1},
{v:19,t:"Ninguém reflete, ninguém tem conhecimento nem inteligência para dizer: Metade dela eu queimei no fogo, sobre as suas brasas assei pão, assei carne e comi; e do resto farei uma abominação? Vou me prostrar diante de um pedaço de pau?"},
{v:20,t:"Ele se alimenta de cinzas; o seu coração enganado o desvia, e ele não consegue salvar a sua vida nem dizer: Não é uma mentira o que tenho na mão direita?"},
{s:"Volta para mim"},
{v:21,l:["Lembra-te disto, Jacó,","e tu, Israel, pois és o meu servo;","eu te formei, tu és o meu servo,","Israel, eu não te esquecerei."]},
{v:22,l:["Dissipei como uma nuvem as tuas transgressões","e como uma neblina os teus pecados;","volta para mim,","pois eu te resgatei."],np:1},
{v:23,l:["Gritai de alegria, céus, pois o Senhor agiu;","exultai, profundezas da terra;","montes, irrompei em gritos de alegria,","e tu, floresta, com todas as tuas árvores,","pois o Senhor resgatou Jacó","e manifesta a sua glória em Israel."],np:1},
{s:"Ciro, instrumento do Senhor"},
{v:24,l:["Assim diz o Senhor, o teu redentor,","que te formou desde o ventre materno:","Eu sou o Senhor, que fiz todas as coisas,","que sozinho estendi os céus,","que firmei a terra: quem estava comigo?"]},
{v:25,l:["Eu frustro os sinais dos adivinhos","e faço dos feiticeiros uns loucos;","faço recuar os sábios","e torno tolo o seu saber;"],np:1},
{v:26,l:["eu confirmo a palavra do meu servo","e realizo o plano dos meus mensageiros;","eu digo a Jerusalém: Serás habitada!","E às cidades de Judá: Sereis reconstruídas!","Eu levantarei as suas ruínas."],np:1},
{v:27,l:["Eu digo ao abismo: Seca-te!","Eu secarei os teus rios."],np:1},
{v:28,l:["Eu digo de Ciro: É o meu pastor,","ele cumprirá toda a minha vontade,","dizendo a Jerusalém: Serás reconstruída!","E ao templo: Serás fundado!"],np:1}
];

window.TEXTOS_SEED["isaias"][45] = [
{s:"O Senhor chama Ciro"},
{v:1,l:["Assim diz o Senhor ao seu ungido, a Ciro,","que tomei pela mão direita,","para submeter diante dele as nações","e desarmar os reis,","para abrir diante dele as portas,","e os portões não ficarão fechados:"],n:"Ungido: em hebraico mashiah, messias. É o único lugar da Bíblia em que um rei pagão recebe este título, como instrumento de Deus para libertar Israel."},
{v:2,l:["Eu irei à tua frente","e aplanarei as montanhas;","despedaçarei as portas de bronze","e quebrarei as trancas de ferro."],np:1},
{v:3,l:["Eu te darei os tesouros escondidos","e as riquezas guardadas em segredo,","para que saibas que eu sou o Senhor,","que te chamo pelo nome, o Deus de Israel."],np:1},
{v:4,l:["Por causa de Jacó, meu servo,","e de Israel, o meu escolhido,","eu te chamei pelo nome;","dei-te um título, embora não me conhecesses."],np:1},
{v:5,l:["Eu sou o Senhor, e não há outro:","fora de mim não há Deus.","Eu te cingi, embora não me conhecesses,"],np:1},
{v:6,l:["para que se saiba, do nascer ao pôr do sol,","que não há nenhum fora de mim.","Eu sou o Senhor, e não há outro;"],np:1},
{v:7,l:["eu formo a luz e crio as trevas,","faço a paz e crio a desgraça:","eu, o Senhor, faço todas estas coisas."],np:1,n:"Nota do tradutor: a desgraça (em hebraico ra, mal) não é o mal moral, mas a calamidade. O texto afirma que tudo está nas mãos do único Deus, e não de duas divindades rivais, uma do bem e outra do mal."},
{v:8,l:["Céus, derramai lá do alto o orvalho,","e que as nuvens façam chover a justiça;","que a terra se abra","e produza a salvação,","e que ao mesmo tempo germine a justiça:","eu, o Senhor, a criei."],np:1,n:"Em latim, Rorate caeli: palavras cantadas na liturgia do Advento."},
{s:"O oleiro e o barro"},
{v:9,l:["Ai de quem discute com aquele que o formou,","ele, um caco entre os cacos de barro!","Acaso o barro dirá ao oleiro: Que estás fazendo?","Ou a tua obra: Ele não tem mãos?"]},
{v:10,l:["Ai de quem diz ao pai: Que estás gerando?","E à mãe: Que estás dando à luz?"],np:1},
{v:11,l:["Assim diz o Senhor,","o Santo de Israel, que o formou:","Quereis interrogar-me sobre o futuro dos meus filhos","e dar-me ordens sobre a obra das minhas mãos?"],np:1},
{v:12,l:["Fui eu que fiz a terra","e criei o homem sobre ela;","as minhas mãos estenderam os céus,","e dou ordens a todo o seu exército."],np:1},
{v:13,l:["Fui eu que o suscitei para a justiça","e aplanarei todos os seus caminhos;","ele reconstruirá a minha cidade","e libertará os meus exilados,","sem preço nem recompensa,","diz o Senhor dos exércitos."],np:1},
{s:"A conversão das nações"},
{v:14,l:["Assim diz o Senhor:","O trabalho do Egito, o comércio da Etiópia","e os sabeus, homens de alta estatura,","passarão para ti e serão teus;","caminharão atrás de ti,","passarão acorrentados,","se prostrarão diante de ti","e te suplicarão:","Só em ti está Deus,","e não há outro, não há outro Deus!"]},
{v:15,l:["Na verdade, tu és um Deus escondido,","ó Deus de Israel, salvador!"],np:1},
{v:16,l:["Ficarão envergonhados e confusos todos juntos,","partirão cobertos de vergonha os fabricantes de ídolos."],np:1},
{v:17,l:["Israel é salvo pelo Senhor com uma salvação eterna;","não ficareis envergonhados nem confusos","pelos séculos dos séculos."],np:1},
{v:18,l:["Pois assim diz o Senhor,","que criou os céus, ele que é Deus,","que formou a terra e a fez, ele que a firmou;","não a criou para ser um caos,","formou-a para ser habitada:","Eu sou o Senhor, e não há outro."],np:1},
{v:19,l:["Não falei às escondidas,","num lugar escuro da terra;","não disse à descendência de Jacó:","Procurai-me em vão.","Eu, o Senhor, falo com justiça","e anuncio o que é reto."],np:1},
{v:20,l:["Reuni-vos e vinde, aproximai-vos juntos,","sobreviventes das nações!","Não têm conhecimento os que carregam o seu ídolo de madeira","e rezam a um deus que não pode salvar."],np:1},
{v:21,l:["Anunciai, apresentai as provas,","consultai-vos juntos:","quem anunciou isto desde o princípio,","quem o predisse há muito tempo?","Não fui eu, o Senhor?","Não há outro Deus fora de mim;","Deus justo e salvador, não há nenhum além de mim."],np:1},
{v:22,l:["Voltai-vos para mim e sereis salvos,","todos os confins da terra,","pois eu sou Deus, e não há outro."],np:1},
{v:23,l:["Juro por mim mesmo:","da minha boca sai a justiça,","uma palavra que não volta atrás:","diante de mim se dobrará todo joelho,","e toda língua jurará por mim."],np:1,n:"Compare Romanos 14,11 e Filipenses 2,10–11."},
{v:24,l:["Dirão: Só no Senhor","estão a justiça e a força.","A ele virão, envergonhados,","todos os que se irritavam contra ele."],np:1},
{v:25,l:["No Senhor será justificada e se gloriará","toda a descendência de Israel."],np:1}
];
